('total_income','Total Income','All revenue recognised in the period.','aggregate','journal_lines','sum','amount_base','{"op":"and","conditions":[{"field":"account_subtype","operator":"in","value":["revenue","other_income"]}]}'::jsonb,NULL,'month',NULL,'prior_period','invert','currency',NULL,0,1,NULL,NULL,true),
('total_expenses','Total Expenses','All operating and non-operating costs.','aggregate','journal_lines','sum','amount_base','{"op":"and","conditions":[{"field":"account_subtype","operator":"in","value":["cogs","opex","depreciation","amortisation","interest","tax"]}]}'::jsonb,NULL,'month',NULL,'prior_period','natural','currency',NULL,0,1,NULL,NULL,true),
('monthly_expenses','Monthly Expenses','Cost of sales plus operating expenses.','aggregate','journal_lines','sum','amount_base','{"op":"and","conditions":[{"field":"account_subtype","operator":"in","value":["cogs","opex"]}]}'::jsonb,NULL,'month',NULL,'prior_period','natural','currency',NULL,0,1,NULL,NULL,true),
('salaries','Salaries & Benefits','Payroll cost including benefits.','aggregate','journal_lines','sum','amount_base','{"op":"and","conditions":[{"field":"account_code","operator":"in","value":["6000","6050"]}]}'::jsonb,NULL,'month',NULL,'prior_period','natural','currency',NULL,0,1,NULL,NULL,true),
('marketing_spend','Marketing Spend',NULL,'aggregate','journal_lines','sum','amount_base','{"op":"and","conditions":[{"field":"account_code","operator":"=","value":"6200"}]}'::jsonb,NULL,'month',NULL,'prior_period','natural','currency',NULL,0,1,NULL,NULL,true),
('expense_by_category','Expense by Category','Operating spend broken down by account.','aggregate','journal_lines','sum','amount_base','{"op":"and","conditions":[{"field":"account_subtype","operator":"in","value":["cogs","opex"]}]}'::jsonb,'account_name','month',NULL,'prior_period','natural','currency',NULL,0,1,NULL,NULL,true),
('income_by_source','Income by Source System',NULL,'aggregate','journal_lines','sum','amount_base','{"op":"and","conditions":[{"field":"account_subtype","operator":"in","value":["revenue","other_income"]}]}'::jsonb,'source','month',NULL,'prior_period','invert','currency',NULL,0,1,NULL,NULL,true),
('net_profit','Net Profit','Total income minus total expenses.','formula',NULL,NULL,NULL,'{}'::jsonb,NULL,'month','{"type":"binary","op":"-","left":{"type":"metric","key":"total_income"},"right":{"type":"metric","key":"total_expenses"}}'::jsonb,'prior_period','natural','currency',NULL,0,1,NULL,NULL,true),
('net_profit_margin','Net Profit Margin',NULL,'formula',NULL,NULL,NULL,'{}'::jsonb,NULL,'month','{"type":"binary","op":"*","left":{"type":"call","fn":"safe_divide","args":[{"type":"metric","key":"net_profit"},{"type":"metric","key":"total_income"}]},"right":{"type":"number","value":100}}'::jsonb,'prior_period','natural','percent',NULL,1,1,12,'{"good":12,"warn":8,"direction":"higher_is_better"}'::jsonb,true),
('gross_profit','Gross Profit',NULL,'formula',NULL,NULL,NULL,'{}'::jsonb,NULL,'month','{"type":"binary","op":"-","left":{"type":"metric","key":"total_income"},"right":{"type":"metric","key":"cost_of_sales"}}'::jsonb,'prior_period','natural','currency',NULL,0,1,NULL,NULL,true),
